const PALETTE = ["#00FFFF", "#008080", "#FF4500", "#FFD700", "#808080", "#303030", "#101010"];

const PLAYER_SPEED = 200;
const PLAYER_HP_MAX = 100;

const ENEMY_HP_MAX = 300;
const ENEMY_ATTACK_COOLDOWN = 3;
const ENEMY_PROJECTILE_SPEED = 150;
const ENEMY_PROJECTILE_DAMAGE = 15;

const SUBSYSTEM_HP = 50;

// Particle configurations
const PARTICLE_MECH_HIT = { count: 8, speed: 100, size: 3, life: 0.3, colors: [PALETTE[0], PALETTE[4]], gravity: 300 };
const PARTICLE_SUBSYSTEM_DESTROY = { count: 20, speed: 150, size: 4, life: 0.5, colors: [PALETTE[2], PALETTE[3], PALETTE[4]], gravity: 400, spread: GF.math.TAU };
const PARTICLE_ENEMY_DEFEAT = { count: 50, speed: 200, size: 5, life: 0.7, colors: [PALETTE[2], PALETTE[3], PALETTE[4], PALETTE[5]], gravity: 500, spread: GF.math.TAU };
const PARTICLE_HP_REPAIR = { count: 10, speed: 80, size: 3, life: 0.4, colors: [PALETTE[0], PALETTE[3]], gravity: -100, dir: -Math.PI / 2, spread: Math.PI / 4 };

let game;

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.radius = 20;
    this.hp = PLAYER_HP_MAX;
    this.iframes = 0;
    this.dodgeDuration = 0;
  }

  update(dt) {
    if (this.iframes > 0) this.iframes -= dt;
    if (this.dodgeDuration > 0) this.dodgeDuration -= dt;

    let dx = 0;
    let dy = 0;
    if (game.input.keys['KeyW'] || game.input.keys['ArrowUp']) dy -= 1;
    if (game.input.keys['KeyS'] || game.input.keys['ArrowDown']) dy += 1;
    if (game.input.keys['KeyA'] || game.input.keys['ArrowLeft']) dx -= 1;
    if (game.input.keys['KeyD'] || game.input.keys['ArrowRight']) dx += 1;

    if (dx !== 0 || dy !== 0) {
      const mag = Math.sqrt(dx * dx + dy * dy);
      if (mag > 0) {
        this.x += (dx / mag) * PLAYER_SPEED * dt;
        this.y += (dy / mag) * PLAYER_SPEED * dt;
      }
    }

    this.x = GF.math.clamp(this.x, this.radius, game.W - this.radius);
    this.y = GF.math.clamp(this.y, this.radius, game.H - this.radius);

    if (game.input.pressed('Space') && this.dodgeDuration <= 0) {
      this.dodgeDuration = 0.2; // Dodge for 0.2 seconds
      this.iframes = 0.2;
      GF.Sfx.beep({ freq: 800, to: 1200, dur: 0.1, type: 'triangle', vol: 0.2 });
    }
  }

  draw(ctx) {
    ctx.save();
    ctx.translate(this.x, this.y);

    // Draw body
    GF.Draw.roundRect(ctx, -15, -15, 30, 30, 5, PALETTE[0]);

    // Draw outline for dodge or iframes
    if (this.dodgeDuration > 0 || this.iframes > 0) {
      ctx.strokeStyle = PALETTE[3];
      ctx.lineWidth = 3;
      ctx.globalAlpha = Math.abs(Math.sin(game.time * 15));
      GF.Draw.roundRect(ctx, -18, -18, 36, 36, 8, 'transparent'); // Draw only outline
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Draw HP bar
    const hpWidth = 40;
    const hpHeight = 5;
    const hpX = -hpWidth / 2;
    const hpY = this.radius + 10;
    GF.Draw.roundRect(ctx, hpX, hpY, hpWidth, hpHeight, 2, PALETTE[5]); // Background
    GF.Draw.roundRect(ctx, hpX, hpY, hpWidth * (this.hp / PLAYER_HP_MAX), hpHeight, 2, PALETTE[0]); // Current HP

    ctx.restore();
  }

  takeDamage(amount) {
    if (this.iframes > 0) return;
    this.hp -= amount;
    this.iframes = 0.5; // Short invulnerability after hit
    game.shake(4, 0.2);
    game.flash(PALETTE[2], 0.4);
    game.burst(this.x, this.y, PARTICLE_MECH_HIT);
    GF.Sfx.noise({ dur: 0.15, vol: 0.4, freq: 800 });
    game.addScore(-10); // player_damage_taken_penalty
    if (this.hp <= 0) {
      game.gameOver({ message: 'Core Integrity Lost!' });
    }
  }

  repair(amount) {
    const oldHp = this.hp;
    this.hp = GF.math.clamp(this.hp + amount, 0, PLAYER_HP_MAX);
    if (this.hp > oldHp) {
      game.burst(this.x, this.y, PARTICLE_HP_REPAIR);
      GF.Sfx.beep({ freq: 1000, to: 1200, dur: 0.05, type: 'sine', vol: 0.1 }); // hp_regen sfx
      game.addScore(5); // hp_restored_score_bonus
    }
  }
}

class EnemySubsystem {
  constructor(name, x, y, radius, effect, color) {
    this.name = name;
    this.x = x;
    this.y = y;
    this.radius = radius;
    this.hp = SUBSYSTEM_HP;
    this.effect = effect;
    this.color = color;
    this.isDestroyed = false;
    this.targeted = false;
    this.flashAlpha = 0;
  }

  takeDamage(amount) {
    if (this.isDestroyed) return;
    this.hp -= amount;
    this.flashAlpha = 0.6;
    GF.Sfx.beep({ freq: 200, to: 100, dur: 0.08, type: 'sawtooth', vol: 0.3 }); // enemy_subsystem_hit
    game.addScore(15); // enemy_subsystem_hit_score
    if (this.hp <= 0) {
      this.hp = 0;
      this.isDestroyed = true;
      game.burst(this.x, this.y, PARTICLE_SUBSYSTEM_DESTROY);
      game.shake(6, 0.3);
      game.hitStop(0.1);
      GF.Sfx.beep({ freq: 150, to: 75, dur: 0.2, type: 'sawtooth', vol: 0.5 }); // enemy_subsystem_destroy
      game.addScore(50); // enemy_subsystem_destroyed_score
    }
  }

  draw(ctx) {
    if (this.isDestroyed) return;
    ctx.fillStyle = this.color;
    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, GF.math.TAU);
    ctx.fill();
    ctx.globalAlpha = 1;

    if (this.targeted) {
      ctx.strokeStyle = PALETTE[3];
      ctx.lineWidth = 3;
      ctx.globalAlpha = Math.abs(Math.sin(game.time * 10)); // Pulsing outline
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius + 5, 0, GF.math.TAU);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    if (this.flashAlpha > 0) {
      ctx.fillStyle = PALETTE[3]; // Amber for critical hit/flash
      ctx.globalAlpha = this.flashAlpha;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius + 2, 0, GF.math.TAU);
      ctx.fill();
      ctx.globalAlpha = 1;
      this.flashAlpha = Math.max(0, this.flashAlpha - game.dt * 5);
    }

    // HP bar
    if (this.hp < SUBSYSTEM_HP) {
      ctx.strokeStyle = PALETTE[5];
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius + 7, 0, GF.math.TAU * (this.hp / SUBSYSTEM_HP));
      ctx.stroke();
    }
  }
}

class EnemyProjectile {
  constructor(x, y, targetX, targetY) {
    this.x = x;
    this.y = y;
    this.radius = 8;
    this.damage = ENEMY_PROJECTILE_DAMAGE;
    const angle = Math.atan2(targetY - y, targetX - x);
    this.vx = Math.cos(angle) * ENEMY_PROJECTILE_SPEED;
    this.vy = Math.sin(angle) * ENEMY_PROJECTILE_SPEED;
    this.life = 3;
  }

  update(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.life -= dt;
  }

  draw(ctx) {
    ctx.fillStyle = PALETTE[2];
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, GF.math.TAU);
    ctx.fill();
  }

  isOffscreen(W, H) {
    return this.x < -this.radius || this.x > W + this.radius || this.y < -this.radius || this.y > H + this.radius || this.life <= 0;
  }
}

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.radius = 60;
    this.hp = ENEMY_HP_MAX;
    this.subsystems = [
      new EnemySubsystem('Weapon', x - 40, y - 20, 15, 'disable_attack', PALETTE[3]),
      new EnemySubsystem('Locomotion', x + 40, y - 20, 15, 'slow_movement', PALETTE[0]),
      new EnemySubsystem('Power Core', x, y + 40, 20, 'explode', PALETTE[2])
    ];
    this.projectiles = [];
    this.attackTimer = ENEMY_ATTACK_COOLDOWN;
    this.telegraphAlpha = 0;
    this.telegraphDuration = 1;
    this.isDead = false;
    this.targetedSubsystem = null;
  }

  update(dt, player) {
    if (this.isDead) return;

    this.attackTimer -= dt;

    if (this.attackTimer <= this.telegraphDuration) {
      this.telegraphAlpha = GF.math.lerp(0.8, 0, this.attackTimer / this.telegraphDuration);
      if (this.attackTimer <= 0) {
        this.fireProjectile(player);
        this.attackTimer = ENEMY_ATTACK_COOLDOWN;
        this.telegraphAlpha = 0;
      }
    } else {
      this.telegraphAlpha = 0;
    }

    for (const proj of this.projectiles) {
      proj.update(dt);
      if (GF.math.dist(proj.x, proj.y, player.x, player.y) < proj.radius + player.radius) {
        player.takeDamage(proj.damage);
        proj.life = 0; // Destroy projectile on hit
      }
    }
    this.projectiles = this.projectiles.filter(p => !p.isOffscreen(game.W, game.H));

    // Subsystem targeting logic
    this.targetedSubsystem = null;
    let closestDist = Infinity;
    for (const sub of this.subsystems) {
      if (sub.isDestroyed) continue;
      // Calculate subsystem's absolute position for distance check
      const subAbsX = this.x + (sub.x - this.x);
      const subAbsY = this.y + (sub.y - this.y);
      const d = GF.math.dist(game.input.pointer.x, game.input.pointer.y, subAbsX, subAbsY);
      if (d < sub.radius && d < closestDist) {
        this.targetedSubsystem = sub;
        closestDist = d;
      }
      sub.targeted = false;
    }
    if (this.targetedSubsystem) {
      this.targetedSubsystem.targeted = true;
      if (game.input.pointer.clicked) {
        this.targetedSubsystem.takeDamage(10); // Simulate player attack
        GF.Sfx.beep({ freq: 400, dur: 0.05, type: 'sine', vol: 0.1 });
      }
    }

    if (this.subsystems.every(s => s.isDestroyed)) {
      this.hp = 0; // Enemy defeated if all subsystems destroyed
    }

    if (this.hp <= 0 && !this.isDead) {
      this.isDead = true;
      game.burst(this.x, this.y, PARTICLE_ENEMY_DEFEAT);
      game.shake(9, 0.5);
      GF.Sfx.beep({ freq: 80, to: 40, dur: 0.5, type: 'sawtooth', vol: 0.6 }); // enemy_explosion_final
      game.addScore(100); // enemy_defeated_score
      game.go('salvage');
    }
  }

  fireProjectile(player) {
    if (this.subsystems[0].isDestroyed) return; // Weapon subsystem disabled
    this.projectiles.push(new EnemyProjectile(this.x, this.y, player.x, player.y));
    GF.Sfx.beep({ freq: 300, to: 200, dur: 0.1, type: 'square', vol: 0.3 }); // enemy_projectile_fire
  }

  draw(ctx) {
    if (this.isDead) return;

    ctx.save();
    ctx.translate(this.x, this.y);

    // Draw main body
    GF.Draw.roundRect(ctx, -this.radius, -this.radius, this.radius * 2, this.radius * 2, 10, PALETTE[5]);

    // Draw telegraph
    if (this.telegraphAlpha > 0) {
      ctx.fillStyle = PALETTE[2];
      ctx.globalAlpha = this.telegraphAlpha * 0.5;
      ctx.beginPath();
      ctx.arc(0, 0, this.radius + 10, 0, GF.math.TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Draw subsystems (relative to enemy's translated origin)
    this.subsystems.forEach(sub => {
      ctx.save();
      // Subsystem positions are relative to the enemy's center, so we need to adjust for the enemy's translation.
      // The sub.x and sub.y are already absolute coordinates in the world, so we need to draw them relative to the enemy's *current* translated origin.
      // The original code had `sub.x - this.x` which is correct for drawing relative to the enemy's center if sub.x was absolute.
      // Since sub.x, sub.y are already absolute positions calculated in the constructor, we need to draw them at their absolute positions.
      // However, the Enemy class translates its context to its own x,y. So the subsystem's x,y must be relative to the enemy's center.
      // Let's re-evaluate: Enemy constructor sets sub.x, sub.y as absolute, e.g., `x - 40`. When Enemy draws, it translates to `this.x, this.y`.
      // So, to draw the subsystem at its correct absolute position, we need to draw it at `(sub.x - this.x), (sub.y - this.y)` relative to the translated origin.
      // This means the previous code was actually correct for the way subsystems were initialized.
      ctx.translate(sub.x - this.x, sub.y - this.y); 
      sub.draw(ctx);
      ctx.restore();
    });

    ctx.restore();

    // Draw projectiles (absolute positions)
    for (const proj of this.projectiles) {
      proj.draw(ctx);
    }
  }
}

// Background elements
let bgOffset = 0;
let gridOffset = 0;

function drawBackground(ctx, W, H, time) {
  // Industrial silhouettes
  ctx.fillStyle = PALETTE[6];
  bgOffset = (bgOffset + 10 * game.dt) % W;
  const silhouetteWidth = 200;
  const silhouetteHeight = 150;
  for (let i = -1; i < W / silhouetteWidth + 1; i++) {
    const x = (i * silhouetteWidth + bgOffset) - W/4; // Adjust starting X position
    ctx.beginPath();
    ctx.moveTo(x, H);
    ctx.lineTo(x + silhouetteWidth * 0.2, H - silhouetteHeight);
    ctx.lineTo(x + silhouetteWidth * 0.5, H - silhouetteHeight + 50);
    ctx.lineTo(x + silhouetteWidth * 0.8, H - silhouetteHeight);
    ctx.lineTo(x + silhouetteWidth, H);
    ctx.fill();
  }

  // Subtle grid lines
  ctx.strokeStyle = PALETTE[5];
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.1;
  gridOffset = (gridOffset + 20 * game.dt) % 40;
  for (let x = gridOffset; x < W; x += 40) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H);
    ctx.stroke();
  }
  for (let y = gridOffset; y < H; y += 40) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // Vignette
  GF.Draw.vignette(ctx, W, H, 0.4);
}

const playScene = {
  init() {
    this.player = new Player(game.W / 4, game.H / 2);
    this.enemy = new Enemy(game.W * 0.75, game.H / 2);
    this.musicLoop = null;
  },
  reset() {
    this.player = new Player(game.W / 4, game.H / 2);
    this.enemy = new Enemy(game.W * 0.75, game.H / 2);
    this.startMusic();
  },
  startMusic() {
    if (this.musicLoop) clearInterval(this.musicLoop);
    // Minimalist synth pulse
    this.musicLoop = setInterval(() => {
      if (game.state === 'playing') {
        GF.Sfx.beep({ freq: 100, dur: 0.4, type: 'sine', vol: 0.05, delay: 0 });
        GF.Sfx.beep({ freq: 101, dur: 0.4, type: 'sine', vol: 0.05, delay: 0.2 });
      }
    }, 1200);
  },
  update(dt) {
    game.dt = dt; // Store dt for particle updates

    // Auto-play logic for probe
    if (game.state === 'playing') {
      // Simulate player movement (WASD) to ensure input is registered
      const keys = ['KeyW', 'KeyA', 'KeyS', 'KeyD'];
      const randomKey = GF.math.pick(keys);
      game.input.keys[randomKey] = true;
      // Simulate mouse clicks for subsystem targeting
      if (game.time % 0.5 < dt) { // Click every 0.5 seconds
        game.input.pointer.clicked = true;
        // Position pointer over a random subsystem to ensure hits
        if (this.enemy && this.enemy.subsystems.length > 0) {
          const targetSub = GF.math.pick(this.enemy.subsystems.filter(s => !s.isDestroyed));
          if (targetSub) {
            game.input.pointer.x = targetSub.x;
            game.input.pointer.y = targetSub.y;
          }
        }
      }
    }

    this.player.update(dt);
    this.enemy.update(dt, this.player);
  },
  draw(ctx) {
    drawBackground(ctx, game.W, game.H, game.time);
    this.player.draw(ctx);
    this.enemy.draw(ctx);

    // HUD
    GF.Draw.text(ctx, `HP: ${this.player.hp}/${PLAYER_HP_MAX}`, game.W - 100, 44, { size: 20, color: PALETTE[0], align: 'right' });
  }
};

const salvageScene = {
  init() {
    this.salvagedComponent = GF.math.pick(['Weapon Mod', 'Locomotion Upgrade', 'Energy Cell']);
    this.decisionMade = false;
    this.decisionTimer = 5; // 5 seconds to make a decision
    GF.Sfx.beep({ freq: 700, to: 900, dur: 0.1, type: 'triangle', vol: 0.3 }); // salvage_pickup
  },
  reset() {
    this.init();
  },
  update(dt) {
    if (this.decisionMade) return;

    this.decisionTimer -= dt;
    if (this.decisionTimer <= 0) {
      game.gameOver({ message: 'Salvage Opportunity Lost!' });
      this.decisionMade = true;
      return;
    }

    // Auto-play logic for probe in salvage scene
    if (game.state === 'playing') { // The state is 'playing' even in salvage scene until game.win/gameOver is called
      if (game.time % 1 < dt) { // Make a decision every second
        const decisions = ['INSTALL', 'SECURE', 'DISMANTLE'];
        this.makeDecision(GF.math.pick(decisions));
      }
    }

    if (game.input.pressed('KeyI')) this.makeDecision('INSTALL');
    if (game.input.pressed('KeyS')) this.makeDecision('SECURE');
    if (game.input.pressed('KeyD')) this.makeDecision('DISMANTLE');
    if (game.input.pointer.clicked) {
      const clickX = game.input.pointer.x;
      const clickY = game.input.pointer.y;
      // Check click on buttons
      const btnWidth = 180;
      const btnHeight = 40;
      const btnPadding = 20;

      let btn1X = game.W / 2 - btnWidth / 2 - btnPadding - btnWidth / 2;
      let btn1Y = game.H / 2 + 50;
      if (clickX > btn1X && clickX < btn1X + btnWidth && clickY > btn1Y && clickY < btn1Y + btnHeight) {
        this.makeDecision('INSTALL');
      }

      let btn2X = game.W / 2 - btnWidth / 2 + btnPadding + btnWidth / 2;
      let btn2Y = game.H / 2 + 50;
      if (clickX > btn2X && clickX < btn2X + btnWidth && clickY > btn2Y && clickY < btn2Y + btnHeight) {
        this.makeDecision('SECURE');
      }

      let btn3X = game.W / 2 - btnWidth / 2;
      let btn3Y = game.H / 2 + 100;
      if (clickX > btn3X && clickX < btn3X + btnWidth && clickY > btn3Y && clickY < btn3Y + btnHeight) {
        this.makeDecision('DISMANTLE');
      }
    }
  },
  makeDecision(type) {
    this.decisionMade = true;
    GF.Sfx.beep({ freq: 1000, dur: 0.05, type: 'square', vol: 0.3 }); // ui_confirm
    switch (type) {
      case 'INSTALL':
        playScene.player.repair(30); // Instant effect
        game.addScore(25); // component_installed_score_bonus
        GF.Sfx.beep({ freq: 1200, dur: 0.1, type: 'sine', vol: 0.2 }); // decision_install
        game.win({ message: `Installed ${this.salvagedComponent}!` });
        break;
      case 'SECURE':
        game.addScore(50); // component_secured_score_multiplier (simplified)
        GF.Sfx.beep({ freq: 600, dur: 0.1, type: 'triangle', vol: 0.2 }); // decision_secure
        game.win({ message: `Secured ${this.salvagedComponent}!` });
        break;
      case 'DISMANTLE':
        playScene.player.repair(50); // Emergency repairs
        game.addScore(10); // less bonus for dismantling
        GF.Sfx.beep({ freq: 300, dur: 0.1, type: 'sawtooth', vol: 0.2 }); // decision_dismantle
        game.win({ message: `Dismantled ${this.salvagedComponent} for repairs!` });
        break;
    }
  },
  draw(ctx) {
    drawBackground(ctx, game.W, game.H, game.time);
    ctx.fillStyle = 'rgba(16,16,16,0.8)';
    ctx.fillRect(0, 0, game.W, game.H);

    GF.Draw.text(ctx, 'SALVAGE OPPORTUNITY!', game.W / 2, game.H / 2 - 100, { size: 40, color: PALETTE[3] });
    GF.Draw.text(ctx, `You found a ${this.salvagedComponent}!`, game.W / 2, game.H / 2 - 40, { size: 28, color: PALETTE[0] });

    const btnWidth = 180;
    const btnHeight = 40;
    const btnPadding = 20;

    // INSTALL Button
    let btn1X = game.W / 2 - btnWidth / 2 - btnPadding - btnWidth / 2;
    let btn1Y = game.H / 2 + 50;
    GF.Draw.roundRect(ctx, btn1X, btn1Y, btnWidth, btnHeight, 5, PALETTE[1]);
    GF.Draw.text(ctx, 'I: INSTALL (+HP)', btn1X + btnWidth / 2, btn1Y + btnHeight / 2, { size: 20, color: '#fff' });

    // SECURE Button
    let btn2X = game.W / 2 - btnWidth / 2 + btnPadding + btnWidth / 2;
    let btn2Y = game.H / 2 + 50;
    GF.Draw.roundRect(ctx, btn2X, btn2Y, btnWidth, btnHeight, 5, PALETTE[1]);
    GF.Draw.text(ctx, 'S: SECURE (+Score)', btn2X + btnWidth / 2, btn2Y + btnHeight / 2, { size: 20, color: '#fff' });

    // DISMANTLE Button
    let btn3X = game.W / 2 - btnWidth / 2;
    let btn3Y = game.H / 2 + 100;
    GF.Draw.roundRect(ctx, btn3X, btn3Y, btnWidth, btnHeight, 5, PALETTE[1]);
    GF.Draw.text(ctx, 'D: DISMANTLE (++HP)', btn3X + btnWidth / 2, btn3Y + btnHeight / 2, { size: 20, color: '#fff' });

    GF.Draw.text(ctx, `Time: ${this.decisionTimer.toFixed(1)}s`, game.W / 2, game.H - 40, { size: 18, color: PALETTE[4] });
  }
};

game = new GF.Game({
  id: 'core-awakening-salvage',
  title: 'Core Awakening: Salvage',
  width: 960,
  height: 540,
  palette: PALETTE,
  background: PALETTE[6] // Dark background
});

game.add('play', playScene);
game.add('salvage', salvageScene);

game.titleScreen({
  subtitle: 'WASD/Arrows to move, Space to dodge, Mouse to aim & click to attack subsystems!\nPress any key to start.',
  onStart: () => {
    game.go('play');
    playScene.startMusic();
  }
});
